{"command": "create", "path": "/app/workspace/extract.py", "file_text": "import os
import re
import pytesseract
from PIL import Image, ImageOps
from openpyxl import Workbook

IMG_DIR = "/app/workspace/dataset/img"
OUT_XLSX = "/app/workspace/stat_ocr.xlsx"

EXCLUSION_KEYWORDS = [
    "SUBTOTAL", "SUB TOTAL", "SUB-TOTAL", "SUB-TUTAL",
    "TAX", "GST", "SST", "DISCOUNT", "CHANGE", "CASH TENDERED",
]

PRIORITY_GROUPS = [
    ["GRAND TOTAL"],
    ["TOTAL RM", "TOTAL: RM"],
    ["TOTAL AMOUNT"],
    ["TOTAL DUE", "AMOUNT DUE", "BALANCE DUE", "NETT TOTAL", "NET TOTAL", "TOTAL", "AMOUNT"],
]

NUM_RE = re.compile(r"(\d{1,3}(?:,\d{3})+\.\d{2}|\d+\.\d{2})")


def run_ocr(path):
    img = Image.open(path)
    text_default = pytesseract.image_to_string(img)

    w, h = img.size
    img2 = img.resize((w * 2, h * 2))
    img2 = ImageOps.grayscale(img2)
    img2 = ImageOps.autocontrast(img2)
    text_pp = pytesseract.image_to_string(img2, config="--psm 6")

    return text_default, text_pp


def extract_date(text):
    # Look for date patterns like DD/MM/YYYY, DD-MM-YYYY, DD/MM/YY, DD-MM-YY
    patterns = [
        re.compile(r"\b(\d{1,2})[/\-](\d{1,2})[/\-](\d{4})\b"),
        re.compile(r"\b(\d{1,2})[/\-](\d{1,2})[/\-](\d{2})\b"),
    ]
    for pat in patterns:
        for m in pat.finditer(text):
            d, mo, y = m.group(1), m.group(2), m.group(3)
            try:
                d_i = int(d)
                m_i = int(mo)
                y_i = int(y)
                if len(y) == 2:
                    y_i = 2000 + y_i if y_i < 70 else 1900 + y_i
                if 1 <= d_i <= 31 and 1 <= m_i <= 12 and 2000 <= y_i <= 2099:
                    return f"{y_i:04d}-{m_i:02d}-{d_i:02d}"
            except ValueError:
                continue
    return None


def _find_number_in_line(line):
    # Find the last valid number in a line (or None)
    matches = NUM_RE.findall(line)
    if matches:
        return matches[-1]
    return None


def _clean_num(s):
    return s.replace(",", "")


def _has_excluded(line_upper):
    for kw in EXCLUSION_KEYWORDS:
        if kw in line_upper:
            return True
    return False


def extract_total_from_text(text):
    """Return (priority_index, value_str) or None. Lower priority_index = higher priority."""
    lines = text.split("\n")
    best = None  # (priority_index, value_str)
    for i, line in enumerate(lines):
        up = line.upper()
        if _has_excluded(up):
            continue
        for prio, keywords in enumerate(PRIORITY_GROUPS):
            matched_kw = None
            for kw in keywords:
                if kw in up:
                    matched_kw = kw
                    break
            if not matched_kw:
                continue
            # Try to extract number from same line
            num = _find_number_in_line(line)
            if num is None and i + 1 < len(lines):
                # Fallback to next line
                next_line = lines[i + 1]
                # Ensure next line isn't itself an excluded line
                if not _has_excluded(next_line.upper()):
                    num = _find_number_in_line(next_line)
            if num is not None:
                if best is None or prio < best[0]:
                    best = (prio, _clean_num(num))
                # Don't break, but higher-priority matches later would be found by iteration
            break  # Don't check lower priority groups for the same line
    return best


def extract_total(text_default, text_pp):
    a = extract_total_from_text(text_default)
    b = extract_total_from_text(text_pp)
    # Choose the one with best (lowest) priority index
    candidates = [c for c in [a, b] if c is not None]
    if not candidates:
        return None
    candidates.sort(key=lambda x: x[0])
    val = candidates[0][1]
    # Format as decimal string with 2 decimals
    try:
        f = float(val)
        return f"{f:.2f}"
    except ValueError:
        return None


def process_all():
    rows = []
    for fname in sorted(os.listdir(IMG_DIR)):
        if not fname.lower().endswith((".jpg", ".jpeg", ".png")):
            continue
        path = os.path.join(IMG_DIR, fname)
        text_default, text_pp = run_ocr(path)
        # For date, try default first, then pp
        date = extract_date(text_default) or extract_date(text_pp)
        total = extract_total(text_default, text_pp)
        rows.append((fname, date, total))
        print(fname, date, total)
    return rows


def write_xlsx(rows):
    wb = Workbook()
    ws = wb.active
    ws.title = "results"
    ws.append(["filename", "date", "total_amount"])
    for r in rows:
        ws.append(list(r))
    wb.save(OUT_XLSX)


if __name__ == "__main__":
    rows = process_all()
    write_xlsx(rows)
    print(f"Wrote {OUT_XLSX}")
"}

{"command": "create", "path": "/app/workspace/extract2.py", "file_text": "import os
import re
import pytesseract
from PIL import Image, ImageOps
from openpyxl import Workbook

IMG_DIR = "/app/workspace/dataset/img"
OUT_XLSX = "/app/workspace/stat_ocr.xlsx"

ALWAYS_EXCLUDE = ["SUBTOTAL", "SUB TOTAL", "SUB-TOTAL",
                  "DISCOUNT", "CHANGE", "CASH TENDERED"]
TAX_WORDS = ["TAX", "GST", "SST"]

PRIORITY_GROUPS = [
    ["GRAND TOTAL"],
    ["TOTAL RM", "TOTAL: RM"],
    ["TOTAL AMOUNT"],
    ["NETT TOTAL", "NET TOTAL", "TOTAL DUE", "AMOUNT DUE", "BALANCE DUE", "TOTAL", "AMOUNT"],
]

NUM_RE = re.compile(r"\d{1,3}(?:,\d{3})+\.\d{2}|\d+\.\d{2}|\d+,\d{2}(?!\d)")


def run_ocr(path):
    img = Image.open(path)
    text_default = pytesseract.image_to_string(img)
    w, h = img.size
    img2 = img.resize((w * 2, h * 2))
    img2 = ImageOps.grayscale(img2)
    img2 = ImageOps.autocontrast(img2)
    text_pp = pytesseract.image_to_string(img2, config="--psm 6")
    return text_default, text_pp


def extract_date(text):
    patterns = [
        re.compile(r"\b(\d{1,2})[/\-](\d{1,2})[/\-](\d{4})\b"),
        re.compile(r"\b(\d{1,2})[/\-](\d{1,2})[/\-](\d{2})\b"),
    ]
    for pat in patterns:
        for m in pat.finditer(text):
            d, mo, y = m.group(1), m.group(2), m.group(3)
            try:
                d_i, m_i, y_i = int(d), int(mo), int(y)
                if len(y) == 2:
                    y_i = 2000 + y_i if y_i < 70 else 1900 + y_i
                if 1 <= d_i <= 31 and 1 <= m_i <= 12 and 2000 <= y_i <= 2099:
                    return f"{y_i:04d}-{m_i:02d}-{d_i:02d}"
            except ValueError:
                continue
    return None


def _norm_num(s):
    # Handles "1,234.56", "234.56", "5,90" (OCR comma-decimal)
    if "." in s:
        # thousands sep case
        return s.replace(",", "")
    else:
        # comma-decimal case (2 digits after comma)
        return s.replace(",", ".")


def _numbers_in(line):
    return [_norm_num(m) for m in NUM_RE.findall(line)]


def _match_priority(line_upper):
    for prio, kws in enumerate(PRIORITY_GROUPS):
        for kw in kws:
            if kw in line_upper:
                return prio, kw
    return None, None


def _should_skip(line_upper, has_priority):
    for kw in ALWAYS_EXCLUDE:
        if kw in line_upper:
            return True
    # Skip tax percentage lines
    if "%" in line_upper:
        return True
    # If no priority keyword, but has tax word, skip
    if not has_priority:
        for kw in TAX_WORDS:
            if kw in line_upper:
                return True
    return False


def extract_total_candidates(text):
    """Return list of (priority, line_index, value_str)."""
    lines = text.split("\n")
    candidates = []
    for i, line in enumerate(lines):
        up = line.upper()
        prio, _ = _match_priority(up)
        if prio is None:
            continue
        if _should_skip(up, has_priority=True):
            continue
        nums = _numbers_in(line)
        if len(nums) > 1:
            # Table-like row with multiple numbers; skip
            continue
        if len(nums) == 1:
            candidates.append((prio, i, nums[0]))
        elif len(nums) == 0 and i + 1 < len(lines):
            # Fallback: next line's last number
            nl = lines[i + 1]
            nl_up = nl.upper()
            # Only if next line is not itself explicitly excluded
            if not any(kw in nl_up for kw in ALWAYS_EXCLUDE):
                nl_nums = _numbers_in(nl)
                if nl_nums:
                    candidates.append((prio, i, nl_nums[-1]))
    return candidates


def count_occurrences(value, texts):
    count = 0
    escaped = re.escape(value)
    pat = re.compile(rf"(?<!\d){escaped}(?!\d)")
    for t in texts:
        # Also count with comma decimal variant
        count += len(pat.findall(t))
        alt = value.replace(".", ",")
        if alt != value:
            pat2 = re.compile(rf"(?<!\d){re.escape(alt)}(?!\d)")
            count += len(pat2.findall(t))
    return count


def extract_total(text_default, text_pp):
    cand_d = extract_total_candidates(text_default)
    cand_p = extract_total_candidates(text_pp)
    all_cand = cand_d + cand_p
    if not all_cand:
        return None
    # Best priority
    best_prio = min(c[0] for c in all_cand)
    same_prio = [c for c in all_cand if c[0] == best_prio]

    # For each OCR source, take the LAST candidate (later position) to represent that source
    last_d = None
    for c in cand_d:
        if c[0] == best_prio:
            last_d = c
    last_p = None
    for c in cand_p:
        if c[0] == best_prio:
            last_p = c

    finalists = [c for c in [last_d, last_p] if c is not None]
    if len(finalists) == 1:
        val = finalists[0][2]
    else:
        v1 = finalists[0][2]
        v2 = finalists[1][2]
        if v1 == v2:
            val = v1
        else:
            # Break tie by frequency across both texts
            f1 = count_occurrences(v1, [text_default, text_pp])
            f2 = count_occurrences(v2, [text_default, text_pp])
            if f2 > f1:
                val = v2
            else:
                val = v1
    try:
        return f"{float(val):.2f}"
    except ValueError:
        return None


def process_all():
    rows = []
    for fname in sorted(os.listdir(IMG_DIR)):
        if not fname.lower().endswith((".jpg", ".jpeg", ".png")):
            continue
        path = os.path.join(IMG_DIR, fname)
        td, tp = run_ocr(path)
        date = extract_date(td) or extract_date(tp)
        total = extract_total(td, tp)
        rows.append((fname, date, total))
        print(fname, date, total)
    return rows


def write_xlsx(rows):
    wb = Workbook()
    ws = wb.active
    ws.title = "results"
    ws.append(["filename", "date", "total_amount"])
    for r in rows:
        ws.append(list(r))
    wb.save(OUT_XLSX)


if __name__ == "__main__":
    rows = process_all()
    write_xlsx(rows)
    print(f"Wrote {OUT_XLSX}")
"}

