    a = extract_total_from_text(text_default)
    b = extract_total_from_text(text_pp)
    # Choose the one with best (lowest) priority index
    candidates = [c for c in [a, b] if c is not None]
    if not candidates:
        return None
    candidates.sort(key=lambda x: x[0])
    val = candidates[0][1]
    # Format as decimal string with 2 decimals
    try:
