    lines = text.split("\n")
    candidates = []
    for i, line in enumerate(lines):
        up = line.upper()
        prio, _ = _match_priority(up)
        if prio is None:
            continue
        if _should_skip(up, has_priority=True):
            continue
        nums = _numbers_in(line)
        if len(nums) > 1:
            # Table-like row with multiple numbers; skip
            continue
        if len(nums) == 1:
            candidates.append((prio, i, nums[0]))
        elif len(nums) == 0 and i + 1 < len(lines):
            # Fallback: next line's last number
            nl = lines[i + 1]
            nl_up = nl.upper()
