    wb = Workbook()
    ws = wb.active
    ws.title = "results"
    ws.append(["filename", "date", "total_amount"])
    for r in rows:
        ws.append(list(r))
    wb.save(OUT_XLSX)


if __name__ == "__main__":
    rows = process_all()
    write_xlsx(rows)
    print(f"Wrote {OUT_XLSX}")
