import re
import pytesseract
from PIL import Image, ImageOps
from openpyxl import Workbook

IMG_DIR = "/app/workspace/dataset/img"
OUT_XLSX = "/app/workspace/stat_ocr.xlsx"

EXCLUSION_KEYWORDS = [
    "SUBTOTAL", "SUB TOTAL", "SUB-TOTAL", "SUB-TUTAL",
    "TAX", "GST", "SST", "DISCOUNT", "CHANGE", "CASH TENDERED",
]

PRIORITY_GROUPS = [
    ["GRAND TOTAL"],
    ["TOTAL RM", "TOTAL: RM"],
    ["TOTAL AMOUNT"],
    ["TOTAL DUE", "AMOUNT DUE", "BALANCE DUE", "NETT TOTAL", "NET TOTAL", "TOTAL", "AMOUNT"],
]

NUM_RE = re.compile(r"(\d{1,3}(?:,\d{3})+\.\d{2}|\d+\.\d{2})")


def run_ocr(path):
    img = Image.open(path)
    text_default = pytesseract.image_to_string(img)

    w, h = img.size
    img2 = img.resize((w * 2, h * 2))
    img2 = ImageOps.grayscale(img2)
    img2 = ImageOps.autocontrast(img2)
    text_pp = pytesseract.image_to_string(img2, config="--psm 6")

    return text_default, text_pp


def extract_date(text):
    # Look for date patterns like DD/MM/YYYY, DD-MM-YYYY, DD/MM/YY, DD-MM-YY
    patterns = [
        re.compile(r"\b(\d{1,2})[/\-](\d{1,2})[/\-](\d{4})\b"),
        re.compile(r"\b(\d{1,2})[/\-](\d{1,2})[/\-](\d{2})\b"),
    ]
    for pat in patterns:
        for m in pat.finditer(text):
            d, mo, y = m.group(1), m.group(2), m.group(3)
            try:
                d_i = int(d)
                m_i = int(mo)
                y_i = int(y)
                if len(y) == 2:
                    y_i = 2000 + y_i if y_i < 70 else 1900 + y_i
                if 1 <= d_i <= 31 and 1 <= m_i <= 12 and 2000 <= y_i <= 2099:
                    return f"{y_i:04d}-{m_i:02d}-{d_i:02d}"
            except ValueError:
                continue
    return None


def _find_number_in_line(line):
    # Find the last valid number in a line (or None)
    matches = NUM_RE.findall(line)
    if matches:
        return matches[-1]
    return None


def _clean_num(s):
    return s.replace(",", "")


def _has_excluded(line_upper):
    for kw in EXCLUSION_KEYWORDS:
        if kw in line_upper:
            return True
    return False


def extract_total_from_text(text):
    """Return (priority_index, value_str) or None. Lower priority_index = higher priority."""
    lines = text.split("\n")
    best = None  # (priority_index, value_str)
    for i, line in enumerate(lines):
        up = line.upper()
        if _has_excluded(up):
            continue
        for prio, keywords in enumerate(PRIORITY_GROUPS):
            matched_kw = None
            for kw in keywords:
                if kw in up:
                    matched_kw = kw
                    break
            if not matched_kw:
                continue
            # Try to extract number from same line
            num = _find_number_in_line(line)
            if num is None and i + 1 < len(lines):
                # Fallback to next line
                next_line = lines[i + 1]
                # Ensure next line isn't itself an excluded line
                if not _has_excluded(next_line.upper()):
                    num = _find_number_in_line(next_line)
            if num is not None:
                if best is None or prio < best[0]:
                    best = (prio, _clean_num(num))
                # Don't break, but higher-priority matches later would be found by iteration
            break  # Don't check lower priority groups for the same line
    return best


